package com.fasterxml.jackson.core.io;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link NumberInput#looksLikeValidNumber(String)} focusing on
 * the fix for issue #1308: allow trailing dot (like "3.").
 */
class NumberInputLooksLikeValidNumberTest {

    @Test
    void testNullAndEmpty() {
        assertFalse(NumberInput.looksLikeValidNumber(null));
        assertFalse(NumberInput.looksLikeValidNumber(""));
    }

    @Test
    void testSingleDigit() {
        assertTrue(NumberInput.looksLikeValidNumber("0"));
        assertTrue(NumberInput.looksLikeValidNumber("5"));
        assertTrue(NumberInput.looksLikeValidNumber("9"));
        assertFalse(NumberInput.looksLikeValidNumber("a"));
        assertFalse(NumberInput.looksLikeValidNumber("-"));
        assertFalse(NumberInput.looksLikeValidNumber("+"));
    }

    @Test
    void testIntegerNumbers() {
        assertTrue(NumberInput.looksLikeValidNumber("123"));
        assertTrue(NumberInput.looksLikeValidNumber("+123"));
        assertTrue(NumberInput.looksLikeValidNumber("-456"));
        assertTrue(NumberInput.looksLikeValidNumber("0123")); // leading zero allowed
    }

    @Test
    void testDecimalNumbers() {
        assertTrue(NumberInput.looksLikeValidNumber("123.456"));
        assertTrue(NumberInput.looksLikeValidNumber("+123.456"));
        assertTrue(NumberInput.looksLikeValidNumber("-456.789"));
        assertTrue(NumberInput.looksLikeValidNumber(".123")); // leading dot allowed
        assertTrue(NumberInput.looksLikeValidNumber("-.456"));
        assertTrue(NumberInput.looksLikeValidNumber("+0.789"));
    }

    @Test
    void testExponentialNotation() {
        assertTrue(NumberInput.looksLikeValidNumber("1e10"));
        assertTrue(NumberInput.looksLikeValidNumber("2.5E-3"));
        assertTrue(NumberInput.looksLikeValidNumber("-3.14e+10"));
        assertTrue(NumberInput.looksLikeValidNumber("+9.99E5"));
        assertTrue(NumberInput.looksLikeValidNumber(".5e2"));
        assertTrue(NumberInput.looksLikeValidNumber("-.2E-3"));
    }

    @Test
    void testTrailingDot() {
        // New cases allowed by the patch (issue #1308)
        assertTrue(NumberInput.looksLikeValidNumber("3."));
        assertTrue(NumberInput.looksLikeValidNumber("+12."));
        assertTrue(NumberInput.looksLikeValidNumber("-456."));
        assertTrue(NumberInput.looksLikeValidNumber("0."));
        assertTrue(NumberInput.looksLikeValidNumber("1234567890."));
    }

    @Test
    void testInvalidNumbers() {
        assertFalse(NumberInput.looksLikeValidNumber("."));
        assertFalse(NumberInput.looksLikeValidNumber("+."));
        assertFalse(NumberInput.looksLikeValidNumber("-."));
        assertFalse(NumberInput.looksLikeValidNumber("e10"));
        assertFalse(NumberInput.looksLikeValidNumber("1.2.3"));
        assertFalse(NumberInput.looksLikeValidNumber("123a"));
        assertFalse(NumberInput.looksLikeValidNumber("--123"));
        assertFalse(NumberInput.looksLikeValidNumber("++456"));
        assertFalse(NumberInput.looksLikeValidNumber("1.2e"));
        assertFalse(NumberInput.looksLikeValidNumber("1.2e+"));
        assertFalse(NumberInput.looksLikeValidNumber("1.2e-"));
        assertFalse(NumberInput.looksLikeValidNumber("inf"));
        assertFalse(NumberInput.looksLikeValidNumber("NaN"));
    }

    @Test
    void testEdgeCasesWithTrailingDot() {
        // Ensure trailing dot only works when there is at least one digit before the dot
        assertTrue(NumberInput.looksLikeValidNumber("1."));
        assertFalse(NumberInput.looksLikeValidNumber(".")); // no digit before dot
        assertFalse(NumberInput.looksLikeValidNumber("+."));
        assertFalse(NumberInput.looksLikeValidNumber("-."));
        // Trailing dot with exponent should not match (PATTERN_FLOAT_TRAILING_DOT does not include exponent)
        assertFalse(NumberInput.looksLikeValidNumber("1.e10"));
        assertFalse(NumberInput.looksLikeValidNumber("2.E-3"));
    }

    @Test
    void testCombinations() {
        // Valid numbers with various formats
        assertTrue(NumberInput.looksLikeValidNumber("0.0"));
        assertTrue(NumberInput.looksLikeValidNumber("+0.0"));
        assertTrue(NumberInput.looksLikeValidNumber("-0.0"));
        assertTrue(NumberInput.looksLikeValidNumber("1234567890.1234567890"));
        assertTrue(NumberInput.looksLikeValidNumber("1.23e-45"));
        assertTrue(NumberInput.looksLikeValidNumber("+9.876E+21"));
        // Trailing dot variations
        assertTrue(NumberInput.looksLikeValidNumber("999."));
        assertTrue(NumberInput.looksLikeValidNumber("+999."));
        assertTrue(NumberInput.looksLikeValidNumber("-999."));
    }
}

