package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class JsonPointerTest {

    @Test
    public void testAppendWithTail() {
        // Original issue reproduction
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tailPointer = original.tail();
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tailPointer);

        // Expected: "/a2/b/c"
        // Before fix: "/a2/a1/b/c"
        assertEquals(JsonPointer.compile("/a2/b/c"), concatenated);
        assertEquals("/a2/b/c", concatenated.toString());
    }

    @Test
    public void testToStringBuilderWithOffset() {
        // Create a JsonPointer with offset (via tail())
        JsonPointer ptr = JsonPointer.compile("/a/b/c");
        JsonPointer tail = ptr.tail(); // Should be "/b/c"

        // toStringBuilder should only include from offset
        StringBuilder sb = tail.toStringBuilder(5);
        assertEquals("/b/c", sb.toString());

        // Verify capacity includes slack
        assertTrue(sb.capacity() >= "/b/c".length() + 5);
    }

    @Test
    public void testToStringBuilderWithoutOffset() {
        // Root pointer has no offset
        JsonPointer ptr = JsonPointer.compile("/a");
        StringBuilder sb = ptr.toStringBuilder(3);
        assertEquals("/a", sb.toString());
        assertTrue(sb.capacity() >= "/a".length() + 3);
    }

    @Test
    public void testAppendPropertyUsesToStringBuilder() {
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer appended = ptr.appendProperty("b/c");

        // Should escape slashes in property name
        assertEquals(JsonPointer.compile("/a/b~1c"), appended);
        assertEquals("/a/b~1c", appended.toString());
    }

    @Test
    public void testAppendIndex() {
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer appended = ptr.appendIndex(0);

        assertEquals(JsonPointer.compile("/a/0"), appended);
        assertEquals("/a/0", appended.toString());
    }

    @Test
    public void testMultipleAppends() {
        JsonPointer base = JsonPointer.compile("/start");
        JsonPointer tail1 = JsonPointer.compile("/middle").tail(); // Should be ""
        JsonPointer tail2 = JsonPointer.compile("/end").tail(); // Should be ""

        // Edge case: appending empty pointers
        JsonPointer result1 = base.append(tail1);
        assertEquals(base, result1);

        JsonPointer result2 = base.append(tail2);
        assertEquals(base, result2);
    }

    @Test
    public void testAppendEmptyPointer() {
        JsonPointer ptr = JsonPointer.compile("/a/b");
        JsonPointer empty = JsonPointer.compile("");

        JsonPointer result = ptr.append(empty);
        assertEquals(ptr, result);

        result = empty.append(ptr);
        assertEquals(ptr, result);
    }

    @Test
    public void testDeepTail() {
        JsonPointer ptr = JsonPointer.compile("/a/b/c/d/e");
        JsonPointer tail = ptr.tail(); // "/b/c/d/e"
        JsonPointer tail2 = tail.tail(); // "/c/d/e"
        JsonPointer tail3 = tail2.tail(); // "/d/e"

        assertEquals("/b/c/d/e", tail.toString());
        assertEquals("/c/d/e", tail2.toString());
        assertEquals("/d/e", tail3.toString());

        // Append from different root
        JsonPointer root = JsonPointer.compile("/root");
        JsonPointer appended = root.append(tail3);
        assertEquals("/root/d/e", appended.toString());
    }
}

