package com.fasterxml.jackson.core;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link JsonPointer} focusing on the changes in version 2.17.
 */
public class JsonPointerTest {

    @Test
    public void testAppendTail() {
        // Original issue #1168
        JsonPointer original = JsonPointer.compile("/a1/b/c");
        JsonPointer tail = original.tail();
        JsonPointer other = JsonPointer.compile("/a2");
        JsonPointer concatenated = other.append(tail);
        JsonPointer expected = JsonPointer.compile("/a2/b/c");
        assertEquals(expected, concatenated);
        assertEquals("/a2/b/c", concatenated.toString());
    }

    @Test
    public void testAppendTailWithEmptyPointer() {
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer tail = JsonPointer.compile("/a/b").tail();
        JsonPointer result = empty.append(tail);
        assertEquals("/b", result.toString());
    }

    @Test
    public void testAppendTailToPointerEndingWithSlash() {
        // In 2.17, trailing slash is not removed
        JsonPointer ptr = JsonPointer.compile("/a/");
        JsonPointer tail = JsonPointer.compile("/b/c").tail();
        JsonPointer result = ptr.append(tail);
        // Should be "/a//b/c"? Actually, note: ptr is "/a/" and tail is "/c" (since tail of "/b/c" is "/c")
        // Let's break down: tail of "/b/c" is "/c", so append should yield "/a//c"
        // But note: compile normalizes multiple slashes? Let's test.
        JsonPointer expected = JsonPointer.compile("/a//c");
        assertEquals(expected, result);
    }

    @Test
    public void testAppendProperty() {
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer result = ptr.appendProperty("b");
        assertEquals("/a/b", result.toString());
    }

    @Test
    public void testAppendPropertyWithEscaping() {
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer result = ptr.appendProperty("b/c");
        // Should escape the slash
        assertEquals("/a/b~1c", result.toString());
    }

    @Test
    public void testAppendPropertyToEmptyPointer() {
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer result = empty.appendProperty("a");
        assertEquals("/a", result.toString());
    }

    @Test
    public void testAppendIndex() {
        JsonPointer ptr = JsonPointer.compile("/a");
        JsonPointer result = ptr.appendIndex(0);
        assertEquals("/a/0", result.toString());
    }

    @Test
    public void testAppendIndexToPointerEndingWithSlash() {
        JsonPointer ptr = JsonPointer.compile("/a/");
        JsonPointer result = ptr.appendIndex(5);
        // Should not remove the trailing slash, so becomes "/a//5"
        JsonPointer expected = JsonPointer.compile("/a//5");
        assertEquals(expected, result);
    }

    @Test
    public void testAppendNegativeIndexThrows() {
        JsonPointer ptr = JsonPointer.compile("/a");
        assertThrows(IllegalArgumentException.class, () -> ptr.appendIndex(-1));
    }

    @Test
    public void testAppendMultipleSegments() {
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer tail = JsonPointer.compile("/b/c/d");
        JsonPointer result = base.append(tail);
        assertEquals("/a/b/c/d", result.toString());
    }

    @Test
    public void testAppendEmptyPointer() {
        JsonPointer base = JsonPointer.compile("/a");
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer result = base.append(empty);
        // Appending empty pointer should not change
        assertEquals("/a", result.toString());
    }

    @Test
    public void testAppendToEmptyPointer() {
        JsonPointer empty = JsonPointer.compile("");
        JsonPointer other = JsonPointer.compile("/b/c");
        JsonPointer result = empty.append(other);
        assertEquals("/b/c", result.toString());
    }

    @Test
    public void testTailAndAppendCombination() {
        JsonPointer ptr = JsonPointer.compile("/a/b/c");
        JsonPointer tail = ptr.tail(); // should be "/b/c"
        JsonPointer base = JsonPointer.compile("/x");
        JsonPointer result = base.append(tail);
        assertEquals("/x/b/c", result.toString());
    }

    @Test
    public void testEqualsWithOffset() {
        JsonPointer ptr1 = JsonPointer.compile("/a/b/c");
        JsonPointer tail1 = ptr1.tail(); // "/b/c"
        JsonPointer ptr2 = JsonPointer.compile("/x/b/c");
        JsonPointer tail2 = ptr2.tail(); // "/b/c"
        assertEquals(tail1, tail2);
    }

    @Test
    public void testHashCodeConsistency() {
        JsonPointer ptr1 = JsonPointer.compile("/a/b/c");
        JsonPointer tail1 = ptr1.tail();
        JsonPointer ptr2 = JsonPointer.compile("/b/c");
        assertEquals(tail1.hashCode(), ptr2.hashCode());
    }

    @Test
    public void testToStringBuilderIndirectly() {
        // Since toStringBuilder is protected, we test via appendProperty which uses it.
        JsonPointer ptr = JsonPointer.compile("/a");
        // This internally uses toStringBuilder
        JsonPointer result = ptr.appendProperty("longPropertyName");
        assertEquals("/a/longPropertyName", result.toString());
    }
}

