package com.fasterxml.jackson.core.util;

import org.junit.Test;
import static org.junit.Assert.*;

public class TextBufferTest {

    @Test
    public void testGetTextBufferConsistencyForEmptyBuffer() {
        // Given: a TextBuffer that is reset with empty
        TextBuffer buffer = new TextBuffer(new BufferRecycler());
        buffer.resetWithEmpty();

        // When: getTextBuffer is called before any other operation
        char[] firstResult = buffer.getTextBuffer();
        // Then: it should not be null, but an empty array (after patch)
        assertNotNull("getTextBuffer should not return null for empty buffer", firstResult);
        assertEquals("getTextBuffer should return empty array for empty buffer", 0, firstResult.length);

        // When: contentsAsString is called (which internally may change state)
        String str = buffer.contentsAsString();
        assertEquals("", str);
        // Then: getTextBuffer should still return an empty array
        char[] secondResult = buffer.getTextBuffer();
        assertNotNull("getTextBuffer should not return null after contentsAsString", secondResult);
        assertEquals("getTextBuffer should return empty array after contentsAsString", 0, secondResult.length);

        // Additionally, both results should be the same reference (or at least both empty)
