package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import java.io.*;
import java.util.Base64;

import org.junit.Test;
import static org.junit.Assert.*;

public class ReaderBasedJsonParserBase64PaddingTest {

    // Test that a Base64 string without padding is accepted when the variant allows it.
    @Test
    public void testBase64MissingPaddingAllowed() throws Exception {
        // Create a Base64Variant that normally uses padding but allows missing padding on read.
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // A Base64 string without padding (length not multiple of 4).
        // We'll use a simple example: "QQ" (which decodes to a single byte 0x41, or 'A').
        // "QQ" is two characters, so it's missing two padding characters.
        // When decoded, it should yield one byte.
        String base64WithoutPadding = "QQ"; // "A" in Base64 without padding.
        String json = "\"" + base64WithoutPadding + "\"";

        JsonFactory factory = new JsonFactory();
        // Create a parser from the JSON string.
        JsonParser parser = factory.createParser(json);
        // Note: setBase64Variant() method doesn't exist on JsonParser.
        // Instead, we need to pass the variant to readBinaryValue() directly.

        // The parser should be positioned at the start token.
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        // Read the binary value.
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int read = parser.readBinaryValue(variant, out);
        byte[] result = out.toByteArray();

        // Verify the decoded data.
        byte[] expected = Base64.getDecoder().decode("QQ=="); // Standard Base64 decoder requires padding.
        // But note: our variant is MIME_NO_LINEFEEDS, which uses the same alphabet.
        // We can compute the expected byte manually: 'Q' -> 16, 'Q' -> 16, so bits: 010000 010000 -> 01000001 -> 0x41.
        assertEquals(1, result.length);
        assertEquals((byte)0x41, result[0]);
        assertEquals(1, read);

        parser.close();
    }

    // Test that a Base64 string without padding still throws exception when padding is required.
    @Test
    public void testBase64MissingPaddingRequired() throws Exception {
        // Use the default MIME_NO_LINEFEEDS which requires padding on read (by default).
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;
        // The default behavior is PADDING_REQUIRED, so missing padding should throw exception.

        String base64WithoutPadding = "QQ";
        String json = "\"" + base64WithoutPadding + "\"";

        JsonFactory factory = new JsonFactory();
        JsonParser parser = factory.createParser(json);

        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        try {
            parser.readBinaryValue(variant, new ByteArrayOutputStream());
            fail("Expected JsonParseException due to missing padding");
        } catch (JsonParseException e) {
            // Expected.
            // The exception message should indicate missing padding.
            assertTrue(e.getMessage().contains("padding"));
        }

        parser.close();
    }

    // Test a longer Base64 string without padding (3 characters -> 2 bytes).
    @Test
    public void testBase64MissingPaddingThreeChars() throws Exception {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // "QUE" decodes to two bytes: 'A' and 'A'? Let's compute: Q=16, U=20, E=4.
        // Bits: 010000 010100 000100 -> 01000001 01000001 -> 0x41, 0x41.
        String base64WithoutPadding = "QUE";
        String json = "\"" + base64WithoutPadding + "\"";

