package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import org.junit.Test;
import static org.junit.Assert.*;

import java.io.IOException;

public class JsonParserDelegateTest {

    // Test that JsonParserDelegate.getNumberTypeFP() delegates to the wrapped parser
    @Test
    public void testGetNumberTypeFPDelegation() throws IOException {
        // Create a real parser and wrap it with a delegate that records the call
        final boolean[] called = {false};
        JsonFactory factory = new JsonFactory();
        String json = "3.14";
        JsonParser realParser = factory.createParser(json);
        realParser.nextToken(); // advance to number

        JsonParserDelegate delegate = new JsonParserDelegate(realParser) {
            @Override
            public JsonParser.NumberTypeFP getNumberTypeFP() throws IOException {
                called[0] = true;
                return super.getNumberTypeFP();
            }
        };

        JsonParser.NumberTypeFP result = delegate.getNumberTypeFP();
        assertTrue(called[0]);
        assertEquals(realParser.getNumberTypeFP(), result);
        realParser.close();
    }

    // Test the default behavior of getNumberTypeFP() for a textual JSON parser
    @Test
    public void testGetNumberTypeFPDefault() throws IOException {
        JsonFactory factory = new JsonFactory();
        String json = "3.14";
        JsonParser parser = factory.createParser(json);
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        // The default implementation should return UNKNOWN for textual formats
        assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
        parser.close();
    }

    // Test that getNumberTypeFP() returns UNKNOWN for non-float tokens
    @Test
    public void testGetNumberTypeFPNonFloat() throws IOException {
        JsonFactory factory = new JsonFactory();
        String json = "123"; // integer
        JsonParser parser = factory.createParser(json);
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        // Even though it's a number, it's not a float, so should return UNKNOWN
        assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
        parser.close();
    }

    // Test with a delegate wrapping a real parser
    @Test
    public void testDelegateWithRealParser() throws IOException {
        JsonFactory factory = new JsonFactory();
        String json = "42.5";
        JsonParser realParser = factory.createParser(json);
        realParser.nextToken(); // advance to number
        JsonParserDelegate delegate = new JsonParserDelegate(realParser);
        // Should return the same as the real parser
        assertEquals(realParser.getNumberTypeFP(), delegate.getNumberTypeFP());
        realParser.close();
    }

    // Additional test to ensure the method exists and works for integer numbers as well
    @Test
    public void testGetNumberTypeFPForInteger() throws IOException {
        JsonFactory factory = new JsonFactory();
        String json = "42";
        JsonParser parser = factory.createParser(json);
        parser.nextToken(); // VALUE_NUMBER_INT
        // Should return UNKNOWN even for integers
        assertEquals(JsonParser.NumberTypeFP.UNKNOWN, parser.getNumberTypeFP());
        parser.close();
    }
}

