package com.fasterxml.jackson.core;

import org.junit.Test;
import static org.junit.Assert.*;

public class VersionTest {

    @Test
    public void testEqualsWithNullSnapshotInfo() {
        // Test case for issue #1141: NPE in Version.equals() if snapshot-info null
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");

        // Should not throw NullPointerException
        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));

        // Also test against a version with non-null snapshot info
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v1.equals(v3));
        assertFalse(v3.equals(v1));
    }

    @Test
    public void testEqualsWithNonNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "ALPHA", "group", "artifact");

        assertTrue(v1.equals(v2));
        assertFalse(v1.equals(v3));
    }

    @Test
    public void testEqualsWithMixedSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, "", "group", "artifact");

        // Both should be considered non-snapshot (empty string is not a snapshot)
        // But they are NOT equal because snapshotInfo differs (null vs empty string)
        // The patch uses Objects.equals which handles null properly
        assertFalse(v1.equals(v2));
        assertFalse(v2.equals(v1));
    }

    @Test
    public void testHashCodeWithNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");

        // Hash codes should be equal for equal objects
        assertEquals(v1.hashCode(), v2.hashCode());

        // Should not throw NullPointerException when computing hash code
        int hashCode = v1.hashCode();
        // Just verify it doesn't throw - no specific value assertion needed
    }

    @Test
    public void testHashCodeWithNonNullSnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");

        assertEquals(v1.hashCode(), v2.hashCode());
    }

    @Test
    public void testHashCodeWithEmptySnapshotInfo() {
        Version v1 = new Version(1, 2, 3, "", "group", "artifact");
        Version v2 = new Version(1, 2, 3, "", "group", "artifact");

        assertEquals(v1.hashCode(), v2.hashCode());
    }

    @Test
    public void testIsSnapshot() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, "", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");

        assertFalse(v1.isSnapshot());
        assertFalse(v2.isSnapshot());
        assertTrue(v3.isSnapshot());
    }

    @Test
    public void testToStringWithNullSnapshotInfo() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertEquals("1.2.3", v.toString());
    }

    @Test
    public void testToStringWithEmptySnapshotInfo() {
        Version v = new Version(1, 2, 3, "", "group", "artifact");
        assertEquals("1.2.3", v.toString());
    }

    @Test
    public void testToStringWithSnapshotInfo() {
        Version v = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertEquals("1.2.3-SNAPSHOT", v.toString());
    }

    @Test
    public void testEqualsReflexive() {
        Version v = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v.equals(v));

        // Also test with null snapshotInfo
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        assertTrue(v2.equals(v2));
    }

    @Test
    public void testEqualsSymmetric() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");

        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v1));

        // Also test with non-null snapshotInfo
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v3.equals(v4));
        assertTrue(v4.equals(v3));
    }

    @Test
    public void testEqualsTransitive() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");
        Version v3 = new Version(1, 2, 3, null, "group", "artifact");

        assertTrue(v1.equals(v2));
        assertTrue(v2.equals(v3));
        assertTrue(v1.equals(v3));

        // Also test with non-null snapshotInfo
        Version v4 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v5 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v6 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertTrue(v4.equals(v5));
        assertTrue(v5.equals(v6));
        assertTrue(v4.equals(v6));
    }

    @Test
    public void testEqualsNull() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertFalse(v.equals(null));

        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v2.equals(null));
    }

    @Test
    public void testEqualsDifferentClass() {
        Version v = new Version(1, 2, 3, null, "group", "artifact");
        assertFalse(v.equals("not a version"));

        Version v2 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v2.equals(new Object()));
    }

    @Test
    public void testEqualsDifferentMajorVersion() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(2, 2, 3, null, "group", "artifact");
        assertFalse(v1.equals(v2));

        // With snapshot info
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(2, 2, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v3.equals(v4));
    }

    @Test
    public void testEqualsDifferentMinorVersion() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 3, 3, null, "group", "artifact");
        assertFalse(v1.equals(v2));

        // With snapshot info
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 3, 3, "SNAPSHOT", "group", "artifact");
        assertFalse(v3.equals(v4));
    }

    @Test
    public void testEqualsDifferentPatchLevel() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 4, null, "group", "artifact");
        assertFalse(v1.equals(v2));

        // With snapshot info
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 2, 4, "SNAPSHOT", "group", "artifact");
        assertFalse(v3.equals(v4));
    }

    @Test
    public void testEqualsDifferentGroupId() {
        Version v1 = new Version(1, 2, 3, null, "group1", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group2", "artifact");
        assertFalse(v1.equals(v2));

        // With snapshot info
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group1", "artifact");
        Version v4 = new Version(1, 2, 3, "SNAPSHOT", "group2", "artifact");
        assertFalse(v3.equals(v4));
    }

    @Test
    public void testEqualsDifferentArtifactId() {
        Version v1 = new Version(1, 2, 3, null, "group", "artifact1");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact2");
        assertFalse(v1.equals(v2));

        // With snapshot info
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact1");
        Version v4 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact2");
        assertFalse(v3.equals(v4));
    }

    @Test
    public void testEqualsDifferentSnapshotInfo() {
        // Test various combinations of snapshot info
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, "", "group", "artifact");
        Version v3 = new Version(1, 2, 3, "SNAPSHOT", "group", "artifact");
        Version v4 = new Version(1, 2, 3, "ALPHA", "group", "artifact");

        // All should be different from each other
        assertFalse(v1.equals(v2));
        assertFalse(v1.equals(v3));
        assertFalse(v1.equals(v4));
        assertFalse(v2.equals(v3));
        assertFalse(v2.equals(v4));
        assertFalse(v3.equals(v4));

        // Symmetry
        assertFalse(v2.equals(v1));
        assertFalse(v3.equals(v1));
        assertFalse(v4.equals(v1));
    }

    @Test
    public void testUnknownVersion() {
        assertTrue(Version.unknownVersion().isUnknownVersion());
        Version v = new Version(0, 0, 0, null, null, null);
        assertTrue(v.equals(Version.unknownVersion()));

        // Test that unknown version equals itself
        assertTrue(Version.unknownVersion().equals(Version.unknownVersion()));
    }

    @Test
    public void testHashCodeConsistency() {
        // Test that hashCode is consistent with equals
        Version v1 = new Version(1, 2, 3, null, "group", "artifact");
        Version v2 = new Version(1, 2, 3, null, "group", "artifact");

        assertTrue(v1.equals(v2));
