package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import org.junit.Test;
import org.junit.Assert;

import java.io.IOException;
import java.io.StringWriter;

public class TokenFilterContextTest {

    // Helper class to test includeEmptyArray and includeEmptyObject behavior
    private static class TestTokenFilter extends TokenFilter {
        private final boolean includeEmptyArray;
        private final boolean includeEmptyObject;

        public TestTokenFilter(boolean includeEmptyArray, boolean includeEmptyObject) {
            this.includeEmptyArray = includeEmptyArray;
            this.includeEmptyObject = includeEmptyObject;
        }

        @Override
        public boolean includeEmptyArray(boolean contentsFiltered) {
            return includeEmptyArray;
        }

        @Override
        public boolean includeEmptyObject(boolean contentsFiltered) {
            return includeEmptyObject;
        }
    }

    @Test
    public void testCloseArrayWithEmptyArrayInclusion() throws IOException {
        // Create a JsonGenerator that writes to a StringWriter
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);

        // Create a root context with a custom filter that includes empty arrays
        TokenFilter filter = new TestTokenFilter(true, false);
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);

        // Create a child array context with start not handled (empty array)
        TokenFilterContext child = root.createChildArrayContext(filter, false);

        // Close the array - should write empty array since includeEmptyArray returns true
        TokenFilterContext result = child.closeArray(gen);

        gen.flush();
        String output = sw.toString();

        // Verify that empty array was written
        Assert.assertEquals("[]", output);
        // Verify that we returned to parent context
        Assert.assertSame(root, result);
    }

    @Test
    public void testCloseArrayWithEmptyArrayExclusion() throws IOException {
        // Create a JsonGenerator that writes to a StringWriter
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);

        // Create a root context with a custom filter that excludes empty arrays
        TokenFilter filter = new TestTokenFilter(false, false);
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);

        // Create a child array context with start not handled (empty array)
        TokenFilterContext child = root.createChildArrayContext(filter, false);

        // Close the array - should NOT write anything since includeEmptyArray returns false
        TokenFilterContext result = child.closeArray(gen);

        gen.flush();
        String output = sw.toString();

        // Verify that nothing was written
        Assert.assertEquals("", output);
        // Verify that we returned to parent context
        Assert.assertSame(root, result);
    }

    @Test
    public void testCloseArrayWithStartHandled() throws IOException {
        // Create a JsonGenerator that writes to a StringWriter
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);

        // Create a root context with INCLUDE_ALL filter
        TokenFilterContext root = TokenFilterContext.createRootContext(TokenFilter.INCLUDE_ALL);

        // Create a child array context with start handled (non-empty array)
        TokenFilterContext child = root.createChildArrayContext(TokenFilter.INCLUDE_ALL, true);

        // Write start array first (since startHandled is true, we need to write it)
        gen.writeStartArray();

        // Close the array - should just write end array
        TokenFilterContext result = child.closeArray(gen);

        gen.flush();
        String output = sw.toString();

        // Verify that complete array was written
        Assert.assertEquals("[]", output);
        // Verify that we returned to parent context
        Assert.assertSame(root, result);
    }

    @Test
    public void testCloseArrayWithNullFilter() throws IOException {
        // Create a JsonGenerator that writes to a StringWriter
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);

        // Create a root context with null filter
        TokenFilterContext root = TokenFilterContext.createRootContext(null);

        // Create a child array context with start not handled
        TokenFilterContext child = root.createChildArrayContext(null, false);

        // Close the array - should NOT write anything since filter is null
        TokenFilterContext result = child.closeArray(gen);

        gen.flush();
        String output = sw.toString();

        // Verify that nothing was written
        Assert.assertEquals("", output);
        // Verify that we returned to parent context
        Assert.assertSame(root, result);
    }

    @Test
    public void testCloseArrayWithIncludeAllFilter() throws IOException {
        // Create a JsonGenerator that writes to a StringWriter
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);

        // Create a root context with INCLUDE_ALL filter
        TokenFilterContext root = TokenFilterContext.createRootContext(TokenFilter.INCLUDE_ALL);

        // Create a child array context with start not handled
        TokenFilterContext child = root.createChildArrayContext(TokenFilter.INCLUDE_ALL, false);

        // Close the array - should NOT write empty array since INCLUDE_ALL doesn't override includeEmptyArray
        TokenFilterContext result = child.closeArray(gen);

        gen.flush();
        String output = sw.toString();

        // Verify that nothing was written (INCLUDE_ALL returns false for includeEmptyArray by default)
        Assert.assertEquals("", output);
        // Verify that we returned to parent context
        Assert.assertSame(root, result);
    }

    @Test
    public void testCloseArrayWithParentWritePath() throws IOException {
        // Create a JsonGenerator that writes to a StringWriter
        StringWriter sw = new StringWriter();
        JsonGenerator gen = new JsonFactory().createGenerator(sw);

        // Create a custom filter that includes empty arrays
        TokenFilter filter = new TestTokenFilter(true, false);

        // Create a root object context
        TokenFilterContext root = TokenFilterContext.createRootContext(filter);
        TokenFilterContext objectContext = root.createChildObjectContext(filter, true);

        // Write start object first
        gen.writeStartObject();

        // Set a field name in the object context
        objectContext.setFieldName("emptyArray");

        // Create an array context as child of object context, with start not handled
        TokenFilterContext arrayContext = objectContext.createChildArrayContext(filter, false);

        // Close the array - should write field name and empty array
        TokenFilterContext result = arrayContext.closeArray(gen);

        // Close the object
        objectContext.closeObject(gen);

        gen.flush();
        String output = sw.toString();

        // Verify that field name and empty array were written
        Assert.assertEquals("{\"emptyArray\":[]}", output);
        // Verify that we returned to object context
        Assert.assertSame(objectContext, result);
    }

    @Test
