        TokenFilterContext arrayContext = root.createChildArrayContext(filter, false);

        // Note: hasCurrentIndex() would return false for an empty array
        // So includeEmptyArray(false) would be called, and our filter returns false

        // Close the array
        TokenFilterContext result = arrayContext.closeArray(gen);

        gen.flush();
