public class JsonFactoryCanonicalizeFieldNamesTest {

    @Test
    public void testNonBlockingByteArrayParserRespectsCanonicalizeFieldNames() throws Exception {
        // Test with CANONICALIZE_FIELD_NAMES disabled
        JsonFactory factory = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        byte[] json = "{\"field1\":1,\"field1\":2}".getBytes("UTF-8");
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        parser.feedInput(json, 0, json.length);

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "field1"
        String field1 = parser.getCurrentName();
        parser.nextToken(); // VALUE_NUMBER_INT 1
        parser.nextToken(); // FIELD_NAME "field1"
        String field2 = parser.getCurrentName();

        // When canonicalization is disabled, these should be different String objects
        assertNotSame("Field names should not be canonicalized when CANONICALIZE_FIELD_NAMES is disabled",
                field1, field2);
        assertEquals("field1", field1);
        assertEquals("field1", field2);
    }

