package com.fasterxml.jackson.core.json.async;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.nio.ByteBuffer;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for verifying that {@link JsonFactory.Feature#CANONICALIZE_FIELD_NAMES} is respected
 * by non-blocking parsers and UTF8DataInputJsonParser.
 */
public class TestCanonicalizeFieldNames {

    // Test for NonBlockingJsonParser (byte array)
    @Test
    public void testNonBlockingByteArrayParserWithCanonicalizeDisabled() throws Exception {
        JsonFactory factory = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        ByteQuadsCanonicalizer symbols = parser.symbolTableForTests();
        assertFalse(symbols.isCanonicalizing(), "Symbol table should not be canonicalizing");
        // When canonicalization is disabled, makeChildOrPlaceholder returns a placeholder with size -1
        assertEquals(-1, symbols.size(), "Placeholder symbol table should have size -1");

        // Feed JSON with repeated field names
        byte[] json = "{\"foo\":1,\"foo\":2}".getBytes("UTF-8");
        parser.feedInput(json, 0, json.length);
        parser.endOfInput();

        // Read tokens
        assertToken(JsonToken.START_OBJECT, parser.nextToken());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("foo", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("foo", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());
        assertToken(JsonToken.END_OBJECT, parser.nextToken());

        // Since canonicalization is disabled, symbol table remains a placeholder with size -1
        assertEquals(-1, symbols.size(), "Placeholder symbol table should keep size -1");
        parser.close();
    }

    @Test
    public void testNonBlockingByteArrayParserWithCanonicalizeEnabled() throws Exception {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        ByteQuadsCanonicalizer symbols = parser.symbolTableForTests();
        assertTrue(symbols.isCanonicalizing(), "Symbol table should be canonicalizing");
        // Initially empty canonicalizing table has size 0
        assertEquals(0, symbols.size(), "Symbol table should be empty initially");

        byte[] json = "{\"foo\":1,\"foo\":2}".getBytes("UTF-8");
        parser.feedInput(json, 0, json.length);
        parser.endOfInput();

        assertToken(JsonToken.START_OBJECT, parser.nextToken());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("foo", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("foo", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());
        assertToken(JsonToken.END_OBJECT, parser.nextToken());

        // With canonicalization enabled, the symbol table should have one entry
        assertEquals(1, symbols.size(), "Symbol table should have one entry when canonicalization is enabled");
        parser.close();
