    }

    // Additional test to cover uncovered lines in _addName: multi-byte UTF-8 field names
    @Test
    public void testNonBlockingParserWithMultiByteFieldNames() throws Exception {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        ByteQuadsCanonicalizer symbols = parser.symbolTableForTests();
        assertTrue(symbols.isCanonicalizing());

        // Field name with multi-byte UTF-8 characters: "αβγ" (Greek letters, 2 bytes each)
        // This will exercise the multi-byte decoding path in _addName
        byte[] json = "{\"αβγ\":42}".getBytes("UTF-8");
        parser.feedInput(json, 0, json.length);
        parser.endOfInput();

        assertToken(JsonToken.START_OBJECT, parser.nextToken());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("αβγ", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(42, parser.getIntValue());
        assertToken(JsonToken.END_OBJECT, parser.nextToken());

        // Symbol table should have stored the multi-byte name
        assertEquals(1, symbols.size(), "Symbol table should have one entry for multi-byte field name");
        parser.close();
    }

    // Test to cover the case where field name length exceeds initial char buffer
    @Test
    public void testNonBlockingParserWithLongFieldName() throws Exception {
        JsonFactory factory = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        ByteQuadsCanonicalizer symbols = parser.symbolTableForTests();

        // Create a field name longer than the initial segment size (likely 200 chars)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 300; i++) {
            sb.append('a');
        }
        String longName = sb.toString();
        byte[] json = ("{\"" + longName + "\":123}").getBytes("UTF-8");
        parser.feedInput(json, 0, json.length);
        parser.endOfInput();

        assertToken(JsonToken.START_OBJECT, parser.nextToken());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(longName, parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(123, parser.getIntValue());
        assertToken(JsonToken.END_OBJECT, parser.nextToken());

        // This exercises expandCurrentSegment() in _addName
        assertEquals(1, symbols.size(), "Symbol table should have one entry for long field name");
        parser.close();
    }

    // Test to verify that non-canonicalizing parsers still work with repeated field names
    @Test
    public void testNonBlockingParserDisabledCanonicalizeRepeatedNames() throws Exception {
        JsonFactory factory = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        NonBlockingJsonParser parser = (NonBlockingJsonParser) factory.createNonBlockingByteArrayParser();
        ByteQuadsCanonicalizer symbols = parser.symbolTableForTests();
        assertEquals(-1, symbols.size(), "Placeholder should have size -1");

        // Use three repeated field names to ensure no side effects
        byte[] json = "{\"f1\":1,\"f2\":2,\"f1\":3}".getBytes("UTF-8");
        parser.feedInput(json, 0, json.length);
        parser.endOfInput();

        assertToken(JsonToken.START_OBJECT, parser.nextToken());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("f1", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(1, parser.getIntValue());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("f2", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());
        assertToken(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("f1", parser.getCurrentName());
        assertToken(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(3, parser.getIntValue());
        assertToken(JsonToken.END_OBJECT, parser.nextToken());

        // Placeholder size remains -1
        assertEquals(-1, symbols.size(), "Placeholder should keep size -1");
        parser.close();
    }

    private static void assertToken(JsonToken expected, JsonToken actual) {
        if (actual != expected) {
            fail("Expected token " + expected + ", got " + actual);
        }
    }
}

