package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import java.io.*;
import java.nio.charset.StandardCharsets;

import static org.junit.Assert.*;
import org.junit.Test;

public class ReaderBasedJsonParserBase64Test {

    private JsonFactory jsonFactory = new JsonFactory();

    // Fixed helper method to properly create a ReaderBasedJsonParser
    private ReaderBasedJsonParser createParser(String json) throws IOException {
        // Use JsonFactory's createParser method instead of manual construction
        return (ReaderBasedJsonParser) jsonFactory.createParser(json);
    }

    @Test
    public void testBase64MissingPaddingAllowed() throws IOException {
        // Create a variant that allows missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Test string "TWF" (3 chars) missing one padding character
        String json = "{\"value\":\"TWF\"}";
        ReaderBasedJsonParser parser = createParser(json);

        // Advance to the field value
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("value", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        // With PADDING_ALLOWED, this should not throw an exception
        byte[] result = parser.getBinaryValue(variant);
        // "TWF" decodes to [77, 97]
        assertArrayEquals(new byte[] {77, 97}, result);
        parser.close();
    }

    @Test
    public void testBase64MissingPaddingRequired() throws IOException {
        // Use default variant which requires padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;

        // Same string without padding should throw an exception
        String json = "{\"value\":\"TWF\"}";
        ReaderBasedJsonParser parser = createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("value", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        try {
            parser.getBinaryValue(variant);
            fail("Expected JsonParseException due to missing padding");
        } catch (JsonParseException e) {
            // Verify it's about missing padding
            assertTrue(e.getMessage().toLowerCase().contains("padding"));
        }
        parser.close();
    }

    @Test
    public void testBase64LongMissingPaddingAllowed() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Test "AA" (2 chars) missing two padding characters
        String json = "{\"diff\":\"AA\"}";
        ReaderBasedJsonParser parser = createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("diff", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        byte[] result = parser.getBinaryValue(variant);
        // "AA" decodes to single byte 0x00
        assertArrayEquals(new byte[] {0}, result);
        parser.close();
    }

    @Test
    public void testBase64WithPaddingWhenAllowed() throws IOException {
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // String with correct padding: "TWFu" (no padding needed, complete 4-char unit)
        // Actually "TWFu" is 4 chars, which is a complete base64 unit, no padding needed
        String json = "{\"value\":\"TWFu\"}";
        ReaderBasedJsonParser parser = createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("value", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        byte[] result = parser.getBinaryValue(variant);
        assertArrayEquals(new byte[] {77, 97, 110}, result);
        parser.close();
    }

    @Test
    public void testBase64MissingPaddingAllowedWithLongString() throws IOException {
        // Test the exact example from the issue
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // This is a long base64 string without padding (from the issue)
        String longBase64 = "";
        String json = "{\"diff\":\"" + longBase64 + "\"}";

        ReaderBasedJsonParser parser = createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("diff", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        // With PADDING_ALLOWED, this should not throw an exception
        byte[] result = parser.getBinaryValue(variant);
        assertNotNull(result);
        // The string length is 572 characters, which is divisible by 4 (572/4=143),
        // so it's actually a complete base64 string without padding needed
