            fail("Expected JsonParseException for invalid padding char");
        } catch (JsonParseException e) {
            // Expected
            // The error message should mention padding character
            assertTrue(e.getMessage().toLowerCase().contains("padding") || 
                      e.getMessage().contains("'='"));
        }
        parser.close();
    }

    @Test
    public void testBase64CompleteUnitWithPaddingWhenRequired() throws IOException {
        // Test that complete 4-char units work with padding required
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;

        // Complete 4-char unit with padding
        String json = "{\"value\":\"TWFu\"}";
        ReaderBasedJsonParser parser = createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("value", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        byte[] result = parser.getBinaryValue(variant);
        assertArrayEquals(new byte[] {77, 97, 110}, result);
        parser.close();
    }

    @Test
    public void testBase64WithCorrectPaddingWhenRequired() throws IOException {
        // Test that strings with correct padding work when padding is required
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS;

        // 3-char input with correct padding
        String json = "{\"value\":\"TWF=\"}";
        ReaderBasedJsonParser parser = createParser(json);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("value", parser.getCurrentName());
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

        byte[] result = parser.getBinaryValue(variant);
        assertArrayEquals(new byte[] {77, 97}, result);
        parser.close();
    }

    @Test
    public void testBase64PaddingOptionalVariant() throws IOException {
        // Test the specific case from the issue: variant with PADDING_ALLOWED
        // should not throw exception for missing padding
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS
                .withReadPadding(Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Various test cases with missing padding
        String[] testCases = {
            "TWF",    // 3 chars, missing 1 padding
            "AA",     // 2 chars, missing 2 padding
            "T",      // 1 char, would need 3 padding
            "TWFu",   // 4 chars, complete unit
            "TWF=",   // 3 chars with padding
            "AA=="    // 2 chars with padding
        };

        for (String base64Str : testCases) {
            String json = "{\"value\":\"" + base64Str + "\"}";
            ReaderBasedJsonParser parser = createParser(json);

            assertEquals(JsonToken.START_OBJECT, parser.nextToken());
            assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
            assertEquals("value", parser.getCurrentName());
            assertEquals(JsonToken.VALUE_STRING, parser.nextToken());

            try {
                byte[] result = parser.getBinaryValue(variant);
                // If we get here, it worked (which is expected for PADDING_ALLOWED)
                assertNotNull(result);
            } catch (JsonParseException e) {
                // Only acceptable if it's not about missing padding
                if (e.getMessage().toLowerCase().contains("missing padding")) {
                    fail("Should not throw missing padding exception for PADDING_ALLOWED variant");
                }
                // Other exceptions (like invalid base64 chars) are OK
            }
            parser.close();
        }
    }
