        Version v1 = new Version(1, 0, 0, "alpha", "com.test", "artifact");
        Version v2 = new Version(1, 0, 0, "beta", "com.test", "artifact");
        assertTrue(v1.compareTo(v2) < 0);  // alpha < beta
        assertTrue(v2.compareTo(v1) > 0);  // beta > alpha

        // Test case 2: One snapshot, one non-snapshot (same version numbers)
        Version v3 = new Version(1, 0, 0, null, "com.test", "artifact");
        Version v4 = new Version(1, 0, 0, "alpha", "com.test", "artifact");
        assertTrue(v4.compareTo(v3) < 0);  // snapshot < release
        assertTrue(v3.compareTo(v4) > 0);  // release > snapshot

        // Test case 3: Both snapshots with same snapshot info
        Version v5 = new Version(1, 0, 0, "alpha", "com.test", "artifact");
        Version v6 = new Version(1, 0, 0, "alpha", "com.test", "artifact");
        assertEquals(0, v5.compareTo(v6));

        // Test case 4: Non-snapshot versions (should be equal)
        Version v7 = new Version(1, 0, 0, null, "com.test", "artifact");
