package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.json.async.NonBlockingJsonParser;
import com.fasterxml.jackson.core.json.async.NonBlockingByteBufferJsonParser;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.DataInput;
import java.io.DataInputStream;
import java.lang.reflect.Field;
import java.nio.ByteBuffer;

import static org.junit.Assert.*;

public class JsonFactoryCanonicalizeFieldNamesTest {

    // Improved helper to get the symbols field from byte-based parsers
    private ByteQuadsCanonicalizer getByteSymbols(JsonParser parser) throws Exception {
        // Try to find the ByteQuadsCanonicalizer field by checking common field names
        Class<?> clazz = parser.getClass();

        // List of possible field names that might hold the ByteQuadsCanonicalizer
        String[] possibleFieldNames = {"_symbols", "_byteSymbolCanonicalizer", "_canonicalizer"};

        for (String fieldName : possibleFieldNames) {
            try {
                Field field = findFieldInHierarchy(clazz, fieldName);
                if (field != null) {
                    field.setAccessible(true);
                    Object value = field.get(parser);
                    if (value instanceof ByteQuadsCanonicalizer) {
                        return (ByteQuadsCanonicalizer) value;
                    }
                }
            } catch (Exception e) {
                // Continue to next field name
            }
        }

        // If we still haven't found it, try to get it from known parser types
        if (parser instanceof UTF8DataInputJsonParser) {
            return getSymbolsFromUTF8DataInputParser((UTF8DataInputJsonParser) parser);
        } else if (parser instanceof NonBlockingJsonParser) {
            return getSymbolsFromNonBlockingParser(parser);
        } else if (parser instanceof NonBlockingByteBufferJsonParser) {
            return getSymbolsFromNonBlockingParser(parser);
        }

        return null;
    }

    private Field findFieldInHierarchy(Class<?> clazz, String fieldName) {
        while (clazz != null && clazz != Object.class) {
            try {
                return clazz.getDeclaredField(fieldName);
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        return null;
    }

    private ByteQuadsCanonicalizer getSymbolsFromUTF8DataInputParser(UTF8DataInputJsonParser parser) throws Exception {
        try {
            Field field = UTF8DataInputJsonParser.class.getDeclaredField("_symbols");
            field.setAccessible(true);
            return (ByteQuadsCanonicalizer) field.get(parser);
        } catch (NoSuchFieldException e) {
            // Try alternative approach
            Field field = UTF8DataInputJsonParser.class.getSuperclass().getDeclaredField("_symbols");
            field.setAccessible(true);
            return (ByteQuadsCanonicalizer) field.get(parser);
        }
    }

    private ByteQuadsCanonicalizer getSymbolsFromNonBlockingParser(JsonParser parser) throws Exception {
        // NonBlockingJsonParser and NonBlockingByteBufferJsonParser extend NonBlockingJsonParserBase
        Class<?> baseClass = parser.getClass().getSuperclass();
        if (baseClass != null && baseClass.getName().contains("NonBlockingJsonParserBase")) {
            Field field = baseClass.getDeclaredField("_symbols");
            field.setAccessible(true);
            return (ByteQuadsCanonicalizer) field.get(parser);
        }
        return null;
    }

    @Test
    public void testUTF8DataInputParserRespectsCanonicalizeSetting() throws Exception {
        // Test with disabled canonicalization
        JsonFactory disabledFactory = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        byte[] json = "{\"field\":1}".getBytes("UTF-8");
        DataInput dataInput = new DataInputStream(new ByteArrayInputStream(json));
        JsonParser parser = disabledFactory.createParser((DataInput) dataInput);
        assertTrue(parser instanceof UTF8DataInputJsonParser);
        ByteQuadsCanonicalizer symbols = getByteSymbols(parser);
        assertNotNull(symbols);
        assertFalse(symbols.isCanonicalizing());
        parser.close();

        // Test with enabled canonicalization
        JsonFactory enabledFactory = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();
        dataInput = new DataInputStream(new ByteArrayInputStream(json));
        parser = enabledFactory.createParser((DataInput) dataInput);
        symbols = getByteSymbols(parser);
        assertNotNull(symbols);
        assertTrue(symbols.isCanonicalizing());
        parser.close();
    }

    @Test
    public void testNonBlockingParsersRespectCanonicalizeSetting() throws Exception {
        // Test both non-blocking parser types with both settings

        // Test with canonicalization disabled
        JsonFactory disabledFactory = JsonFactory.builder()
                .disable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        // Test NonBlockingJsonParser
        JsonParser parser1 = disabledFactory.createNonBlockingByteArrayParser();
        assertTrue(parser1 instanceof NonBlockingJsonParser);
        ByteQuadsCanonicalizer symbols1 = getByteSymbols(parser1);
        assertNotNull(symbols1);
        assertFalse(symbols1.isCanonicalizing());
        parser1.close();

        // Test NonBlockingByteBufferJsonParser
        JsonParser parser2 = disabledFactory.createNonBlockingByteBufferParser();
        assertTrue(parser2 instanceof NonBlockingByteBufferJsonParser);
        ByteQuadsCanonicalizer symbols2 = getByteSymbols(parser2);
        assertNotNull(symbols2);
        assertFalse(symbols2.isCanonicalizing());
        parser2.close();

        // Test with canonicalization enabled
        JsonFactory enabledFactory = JsonFactory.builder()
                .enable(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES)
                .build();

        parser1 = enabledFactory.createNonBlockingByteArrayParser();
        symbols1 = getByteSymbols(parser1);
        assertNotNull(symbols1);
        assertTrue(symbols1.isCanonicalizing());
        parser1.close();

        parser2 = enabledFactory.createNonBlockingByteBufferParser();
        symbols2 = getByteSymbols(parser2);
        assertNotNull(symbols2);
        assertTrue(symbols2.isCanonicalizing());
        parser2.close();
    }

    @Test
