    @Test
    public void testBase64WithWhitespaceInMiddleOfUnit() throws IOException {
        // Test that whitespace in the middle of a base64 unit is not allowed
        // This was the original failing test - whitespace should only be allowed BETWEEN units

        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
                Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // "MQ MQ" has whitespace in the middle of what should be a 4-char unit
        // This should fail because whitespace is not allowed within a unit
        String json = "\"MQ MQ\"";

        UTF8StreamJsonParser parser = createParser(json);

        JsonToken token = parser.nextToken();
        assertEquals(JsonToken.VALUE_STRING, token);

        try {
            parser.getBinaryValue(variant);
            fail("Expected JsonParseException for whitespace within base64 unit");
        } catch (JsonParseException e) {
            assertTrue(e.getMessage().toLowerCase().contains("white space"));
        }
        parser.close();
    }

