    @Test
    public void testBase64WithPaddingWhenUsesPaddingButNotRequired() throws IOException {
        // Test the specific case from the issue: MIME variant with PADDING_ALLOWED
        // should accept both padded and unpadded input
        Base64Variant variant = Base64Variants.MIME_NO_LINEFEEDS.withReadPadding(
                Base64Variant.PaddingReadBehaviour.PADDING_ALLOWED);

        // Test both padded and unpadded versions
        String[] testCases = {
            "\"MQ\"",      // unpadded
            "\"MQ==\"",    // padded
            "\"MTI\"",     // unpadded 3 chars
            "\"MTI=\"",    // padded 3 chars
            "\"MTIz\"",    // complete 4 chars
            "\"MTIzNA\"",  // unpadded 5 chars (should decode to 3 bytes)
            "\"MTIzNA==\"", // padded 5 chars
        };

        byte[][] expectedResults = {
            new byte[]{'1'},
            new byte[]{'1'},
            new byte[]{'1', '2'},
            new byte[]{'1', '2'},
            new byte[]{'1', '2', '3'},
            new byte[]{'1', '2', '3', '4'},
            new byte[]{'1', '2', '3', '4'},
        };

        for (int i = 0; i < testCases.length; i++) {
            UTF8StreamJsonParser parser = createParser(testCases[i]);
            JsonToken token = parser.nextToken();
            assertEquals(JsonToken.VALUE_STRING, token);

            byte[] result = parser.getBinaryValue(variant);
            assertArrayEquals("Failed for case " + i + ": " + testCases[i], 
                expectedResults[i], result);
            parser.close();
        }
    }
